# Generated by homebrew/formula.sh in Jleagle/coffee on each release. DO NOT EDIT.
class Coffee < Formula
  desc "Menu bar app for ordering from the coffee shop"
  homepage "https://github.com/Jleagle/coffee"
  url "https://github.com/Jleagle/coffee/archive/refs/tags/v0.1.0.tar.gz"
  sha256 "0f8199897f4a2b843d6b2ecaf6a6fa8219d9bb18c6152fe1a4499604eb5aaa28"

  livecheck do
    skip "Updated by the release workflow."
  end

  depends_on xcode: ["15.0", :build]
  # Matches LSMinimumSystemVersion in bundle.sh.
  depends_on macos: :ventura

  def install
    # Homebrew already sandboxes the build and SwiftPM's own sandbox cannot
    # nest inside it.
    system "swift", "build", "-c", "release", "--disable-sandbox"
    # Info.plist + ad-hoc codesign live in bundle.sh, shared with run.sh.
    system "./bundle.sh", ".build/release/coffee-menubar", version.to_s, "Coffee.app"
    prefix.install "Coffee.app"
  end

  # The app used to live in /Applications as a cask. From the Cellar,
  # `brew services start coffee` is what runs it at login.
  service do
    run [opt_prefix/"Coffee.app/Contents/MacOS/coffee-menubar"]
    # Relaunch after a crash, but stay quit when quit from the menu bar.
    keep_alive successful_exit: false
    log_path var/"log/coffee.log"
    error_log_path var/"log/coffee.log"
  end

  # Homebrew adds its own `brew services start coffee` hint after this.
  def caveats
    <<~EOS
      Coffee.app lives in the Cellar, not /Applications. To run it once:
        open #{opt_prefix}/Coffee.app

      After `brew upgrade coffee`, restart it to pick up the new version:
        brew services restart coffee
    EOS
  end

  test do
    assert_match "<string>#{version}</string>", (prefix/"Coffee.app/Contents/Info.plist").read
  end
end
